    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Which 1914 legal case famously stated: "Every human being of adult years and sound mind has a right to determine what shall be done with his own body"?', '["Roe v. Wade", "Schloendorff v. Society of New York Hospital", "Cruzan v. Missouri", "Tarasoff v. Regents"]', 1, 'Judge Cardozo''s ruling in Schloendorff is a foundational statement of the right to bodily integrity in US law.'),
    (v_topic_id, 'The "Tarasoff v. Regents of the University of California" case established that a mental health professional has a:', '["Duty to remain silent at all costs", "Duty to warn or protect a third party if a patient poses a credible threat of serious physical harm", "Duty to prescribe medication", "None of the above"]', 1, 'Tarasoff created a limit to confidentiality when public safety is at immediate risk.'),
    (v_topic_id, 'Which 1979 report established the three core ethical principles for human subjects research: Respect for Persons, Beneficence, and Justice?', '["The Nuremberg Code", "The Belmont Report", "The Declaration of Helsinki", "The Flexner Report"]', 1, 'The Belmont Report is the primary framework for research ethics in the United States.'),
    (v_topic_id, 'An "IRB" (Institutional Review Board) is responsible for:', '["Winning grants", "Ensuring that research studies are ethical and that the rights and welfare of human subjects are protected", "Firing bad researchers", "None of the above"]', 1, 'IRB approval is a legal requirement for all human subjects research receiving federal funding.'),
    (v_topic_id, 'The "Nuremberg Code" was created in response to:', '["A medical error", "Unethical human experimentation conducted by Nazi doctors during World War II", "A bad drug reaction", "None of the above"]', 1, 'The code emphasizes the absolute necessity of voluntary, informed consent in research.'),
    (v_topic_id, 'In research, the principle of "Justice" requires that:', '["The rich get the best drugs", "The burdens and benefits of research are distributed fairly across all groups in society", "Everyone is paid the same", "None of the above"]', 1, 'Justice prevents the exploitation of vulnerable groups for the benefit of more privileged ones.'),
    (v_topic_id, 'A "Phase 1" clinical trial is primarily designed to assess:', '["If the drug works", "The safety and dosage of a new drug in a small group of healthy volunteers", "The long-term side effects", "If the drug is better than the competition"]', 1, 'Phase 1 focuses on human safety and pharmacokinetics.'),
    (v_topic_id, 'Which population is considered "Vulnerable" and requires "Clear and Convincing" justification to be included in a research study?', '["Medical students", "Prisoners", "Professional athletes", "None of the above"]', 1, 'Prisoners are vulnerable because their environment and status may compromise their ability to provide truly voluntary consent.'),
    (v_topic_id, 'The "Declaration of Helsinki" is a set of ethical principles for the medical community regarding human experimentation, developed by the:', '["UN", "World Medical Association (WMA)", "FDA", "NASA"]', 1, 'The Declaration is the international standard for physician-researchers.'),
    (v_topic_id, 'A researcher discovers that their study results were influenced by a "Conflict of Interest" (e.g., they own stock in the drug company). What is the ethical requirement?', '["Hide it", "Full disclosure of the conflict in all publications and presentations of the data", "Stop being a doctor", "None of the above"]', 1, 'Transparency is the primary mechanism for managing conflicts of interest.'),
    (v_topic_id, 'In a "Double-Blind" study, who knows which subjects are receiving the active treatment?', '["The patient", "The doctor", "Only an independent monitor or a data management team not involved in the direct care of the subjects", "Everyone"]', 2, 'Blinding prevents bias in the observation and reporting of results.'),
    (v_topic_id, 'What is "Therapeutic Misconception" in research?', '["A type of allergy", "When a subject believes that a research study is designed to provide them with personalized medical care rather than to produce generalizable knowledge", "A doctor making a mistake", "None of the above"]', 1, 'Researchers must ensure subjects understand the difference between a trial and clinical treatment.'),
    (v_topic_id, 'A "Minimal Risk" study is one where:', '["There is no risk", "The risk of harm is no greater than that encountered in daily life or routine physical/psychological exams", "The risk is 50/50", "None of the above"]', 1, 'Minimal risk studies (like simple surveys) often have a "Streamlined" IRB review process.'),
    (v_topic_id, 'Which of the following is true about "Informed Consent" in research?', '["It is a one-time signature", "It is an ongoing process that continues throughout the subject''s participation in the study", "It is optional for minor studies", "None of the above"]', 1, 'Subjects must be updated on new risks or findings that might change their willingness to participate.'),
    (v_topic_id, 'A researcher uses "De-identified" data from a hospital database. Does this typically require full individual consent from every patient?', '["Yes", "No, most IRBs consider this ''Exempt'' from individual consent as long as the data cannot be traced back to the individuals", "Only if the patients are dead", "None of the above"]', 1, 'Secondary use of de-identified data is a common and ethically accepted research practice.'),
    (v_topic_id, 'The "Tuskegee Syphilis Study" is a infamous example of a failure of:', '["Veracity (deceiving the men about their treatment)", "Justice (exploiting a poor, minority population)", "Beneficence (withholding effective treatment for a dangerous disease)", "All of the above"]', 3, 'Tuskegee is a landmark case that led to the creation of the Belmont Report and modern IRB rules.'),
    (v_topic_id, 'Which legal case involved the "Right to Die" and the definition of death as "Brain Death"?', '["Roe v. Wade", "In re Quinlan (conceptually, though she was PVS)", "People v. Eulo (New York)", "None of the above"]', 2, 'Legal recognition of brain death was a critical step in the evolution of organ transplantation and end-of-life law.'),
    (v_topic_id, 'A "DSMB" (Data and Safety Monitoring Board) has the power to:', '["Stop a clinical trial early if it is found to be clearly harmful or clearly beneficial", "Change the study budget", "Fire the lead researcher", "None of the above"]', 0, 'DSMBs provide an independent layer of safety protection.'),
    (v_topic_id, 'In research on "Pregnant Women," the researcher must ensure that:', '["The risk to the fetus is minimized", "The research provides a direct benefit to the woman or the fetus", "Both parents provide consent whenever possible", "All of the above"]', 3, 'Extra protections are in place for the "Maternal-Fetal" dyad in research.'),
    (v_topic_id, 'Which of the following is an example of "Scientific Misconduct"?', '["Fabrication (making up data)", "Falsification (manipulating data to reach a desired result)", "Plagiarism (stealing others'' work)", "All of the above"]', 3, 'Misconduct undermines the entire foundation of medical progress.'),
    (v_topic_id, 'The "Common Rule" is:', '["A rule about wearing scrubs", "The core set of US federal regulations for the protection of human subjects in research", "A type of hospital policy", "None of the above"]', 1, 'The Common Rule (45 CFR 46) is the legal weight behind the Belmont principles.'),
    (v_topic_id, 'A "Vulnerable" subject is someone whose:', '["Feelings are easily hurt", "Ability to provide truly voluntary and informed consent is compromised by their circumstances", "Income is low", "None of the above"]', 1, 'Vulnerability is about the "Situational" threat to autonomy.'),
    (v_topic_id, 'If a researcher wants to study "Children," they must generally obtain:', '["Parental Consent", "The Child''s Assent (if the child is of appropriate age and cognitive level)", "IRB approval", "All of the above"]', 3, 'The combination of proxy consent and individual assent is the standard for pediatric research.'),
    (v_topic_id, 'Which of the following describes "Incidental Findings" in research (e.g., finding a tumor on an experimental MRI)?', '["A mistake by the researcher", "Findings that are not the primary goal of the study but have potential clinical significance for the subject", "Fake data", "None of the above"]', 1, 'IRBs increasingly require a plan for how and when to disclose incidental findings to subjects.'),
    (v_topic_id, 'A "Community Advisory Board" (CAB) is used in research to:', '["Raise money", "Ensure that the research goals and methods are respectful and relevant to the community being studied", "Control the doctors", "None of the above"]', 1, 'CABs help prevent "Helicopter Research" that exploits communities without providing value.'),
    (v_topic_id, 'Which of the following is true about "AI" and ethics in research?', '["AI has no ethics", "Researchers must ensure that AI algorithms are transparent, free from bias, and that patient data used to train them is properly consented and protected", "AI is always right", "None of the above"]', 1, 'Algorithmic bias is a major emerging concern in medical ethics.'),
    (v_topic_id, 'A "Compassionate Use" protocol is for:', '["Helping poor people", "Individual patients with life-threatening conditions who do not qualify for a clinical trial but have no other options", "Nurses only", "None of the above"]', 1, 'This is also known as "Expanded Access."'),
    (v_topic_id, 'What is "Equipoise" in a clinical trial?', '["A state of balance where there is genuine uncertainty among the medical community about which treatment is better", "A type of balance scale", "When the doctor is bored", "None of the above"]', 0, 'Ethical research requires that a study be based on a legitimate question that hasn''t been answered yet.'),
    (v_topic_id, 'A researcher who "Fails to Publish" negative results is guilty of:', '["Budgeting error", "Publication Bias, which distorts the scientific record and can lead to patient harm", "Laziness", "None of the above"]', 1, 'Negative data is as important as positive data for scientific integrity.'),
    (v_topic_id, 'Which of the following is true about "Genetic Privacy" (GINA Act)?', '["It allows employers to fire you for your DNA", "It prohibits health insurers and employers from discriminating against individuals based on their genetic information", "It is only for celebrities", "None of the above"]', 1, 'The Genetic Information Nondiscrimination Act (2008) is a key protection for patients seeking genetic testing.'),
    (v_topic_id, 'A "Certificate of Confidentiality" (CoC) protects researchers from:', '["Being sued for malpractice", "Being forced by a court to disclose sensitive, identifiable research data (like illegal drug use or HIV status)", "Bad reviews", "None of the above"]', 1, 'CoCs are used to protect subjects in studies involving sensitive behaviors.'),
    (v_topic_id, 'Which of the following is an example of "Non-maleficence" in research?', '["Paying subjects well", "Designing a study to minimize the potential for physical or psychological pain and distress for the participants", "Publishing in a top journal", "None of the above"]', 1, 'The duty to "Do No Harm" applies to researchers as well as clinicians.'),
    (v_topic_id, 'A "Phase 4" clinical trial occurs:', '["Before the drug is made", "After the drug has been approved and is on the market (Post-Marketing Surveillance)", "Only in animals", "None of the above"]', 1, 'Phase 4 monitors for rare or long-term adverse events in the general population.'),
    (v_topic_id, 'Which of the following is true about "Big Data" in medicine?', '["It is always safe", "It poses significant challenges for ''De-identification,'' as multiple datasets can sometimes be combined to ''re-identify'' individuals", "It is only for computers", "None of the above"]', 1, 'Re-identification risk is a major technical and ethical challenge.'),
    (v_topic_id, 'The "Helsinki Declaration" states that the interests of the *subject* should always come before:', '["The interests of science and society", "The interests of the doctor", "The interests of the family", "None of the above"]', 0, 'Individual rights override the "Common Good" in research ethics.'),
    (v_topic_id, 'A researcher offers a $20 gift card for a 2-hour survey. This is:', '["Coercion", "Appropriate ''Reimbursement'' for time and effort", "Undue Inducement", "None of the above"]', 1, 'Reimbursement is allowed; inducement (making it hard to say no) is not.'),
    (v_topic_id, 'Which of the following is a "Material Conflict of Interest"?', '["The researcher likes the drug name", "The researcher receives $100,000 a year in consulting fees from the company making the drug being studied", "The researcher is a fan of the company", "None of the above"]', 1, 'Significant financial relationships must be disclosed and managed.'),
    (v_topic_id, 'A "Protocol Deviation" occurs when:', '["The doctor gets lost", "The researcher does not follow the IRB-approved plan for the study", "The patient is late", "None of the above"]', 1, 'Deviations must be reported to the IRB.'),
    (v_topic_id, 'Which of the following describes "Medical Paternalism" in research?', '["The subject chooses everything", "The researcher deciding for the subject what is best for them without their input", "The IRB choosing everything", "None of the above"]', 1, 'Paternalism is the opposite of respecting autonomy.'),
    (v_topic_id, 'A "Deceptive" research study (e.g., in psychology) can only be approved if:', '["It is funny", "The deception is necessary for the science, the risk is minimal, and subjects are ''Debriefed'' (told the truth) as soon as possible", "The subjects are paid a lot", "None of the above"]', 1, 'Deception is a high-threshold ethical issue.'),
    (v_topic_id, 'Which of the following is true about "Biobanking" (storing tissue samples for future research)?', '["Consent is only needed for the first study", "Subjects must provide ''Broad Consent'' or be updated on the types of future research their samples will be used for", "Samples belong to the doctor", "None of the above"]', 1, 'Biobanking requires careful long-term consent and data protection plans.'),
    (v_topic_id, 'A "Case Report" on a single patient requires:', '["A full clinical trial", "The patient''s specific informed consent to have their case and any identifying images published in a medical journal", "Nothing, it''s just one person", "None of the above"]', 1, 'Privacy and consent apply even to single-case stories.'),
    (v_topic_id, 'The "Right to be Forgotten" in medical data refers to:', '["The doctor forgetting the patient", "A patient''s right to have their data removed from a research database or AI model, where feasible", "A type of amnesia", "None of the above"]', 1, 'This is an emerging right in global data privacy law (like GDPR).'),
    (v_topic_id, 'A researcher "Data Mines" social media to study mental health trends. Is this "Human Subjects Research"?', '["No, it''s public", "In many cases yes, as it involves identifiable private information or interaction with individuals, requiring IRB oversight", "Only if it''s on Twitter", "None of the above"]', 1, 'Digital ethics is a rapidly evolving field.'),
    (v_topic_id, 'Which of the following is a "Prohibited" research practice?', '["Testing a drug on animals first", "Performing research on unconsented subjects (unless in a very narrow, IRB-approved emergency exception)", "Paying researchers a salary", "None of the above"]', 1, 'Unconsented research is a violation of the most basic ethical norms.'),
    (v_topic_id, 'A "Systematic Review" is considered the highest level of evidence because it:', '["Is the longest", "Uses a transparent, reproducible method to synthesize all available high-quality evidence on a topic", "Is written by famous people", "None of the above"]', 1, 'Evidence hierarchy prioritizes synthesis of multiple studies.'),
    (v_topic_id, 'Which of the following is true about "Medical Journals" and ethics?', '["They don''t care", "They require proof of IRB approval and disclosure of all conflicts of interest before publishing a study", "They only publish good news", "None of the above"]', 1, 'Journals are the "gatekeepers" of scientific integrity.'),
    (v_topic_id, 'A researcher who "Self-Experiments" (tests a drug on themselves):', '["Is a hero", "Is still subject to IRB rules if they plan to use the data for generalizable knowledge", "Can do whatever they want", "None of the above"]', 1, 'Even self-experimentation must follow ethical standards if it''s part of formal research.'),
    (v_topic_id, 'Which of the following is an example of "Beneficence" in research?', '["Designing a study that has the potential to lead to a cure for a debilitating disease", "Making sure the researcher is famous", "Getting a high salary", "None of the above"]', 0, 'Beneficence is about the "Good" the research can do for individuals and society.'),
    (v_topic_id, 'The ultimate "Ethical Guardrail" in human subjects research is:', '["The budget", "The researcher''s own moral integrity and commitment to the welfare of their subjects", "The police", "None of the above"]', 1, 'Rules are necessary, but professional virtue is the final defense.');
